from typing import List

def minimumSeconds(nums: List[int]) -> int:
    from collections import defaultdict
    n = len(nums)
    pos = defaultdict(list)
    for i, v in enumerate(nums):
        pos[v].append(i)
    ans = float('inf')
    for p in pos.values():
        mx = 0
        for i in range(len(p)):
            gap = (p[0] + n - p[-1]) if i == 0 else (p[i] - p[i - 1])
            if gap // 2 > mx:
                mx = gap // 2
        if mx < ans:
            ans = mx
    return ans
